'use server'

import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/lib/preferences'

export async function toggleNotifications(): Promise<void> {
  setNotificationPreference(!getNotificationPreference())

  // Refresh the current page so it re-renders with the updated preference,
  // without navigating away. This is Next.js's API for refreshing the
  // current route from within a Server Action (the server-side equivalent
  // of router.refresh()).
  refresh()
}

