import { toggleNotifications } from './actions'
import { getNotificationPreference } from '@/lib/preferences'

// Always render fresh so the page reflects the latest preference on refresh.
export const dynamic = 'force-dynamic'

export default function Home() {
  const enabled = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{enabled ? 'ON' : 'OFF'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

